import java.util.*;
import java.io.*;

public class Main {
    static int n_input, total_nodes, result_value;
    static long[] prefix_sum = new long[15];
    static List<Long>[] sequences = new ArrayList[15];

    static {
        for (int i = 0; i < 15; i++) {
            sequences[i] = new ArrayList<>();
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n_input = Integer.parseInt(br.readLine());

        generate(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(sequences[i]);
        }
        total_nodes = 0;
        for (int i = 1; i <= 9; i++) {
            traverse(i);
        }
        System.out.println(result_value);
    }

    static void generate(int depth, long num) {
        if (depth == 7) return;
        total_nodes++;
        long val = ((total_nodes - num) % 998244353 + 998244353) % 998244353;
        sequences[depth].add(val);
        prefix_sum[depth] = (prefix_sum[depth] + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            generate(depth + 1, num * 10 + digit);
        }
    }

    static void traverse(int x) {
        if (x > n_input) return;
        long lowerBoundLimit = 1000000000L - ((x * 1000000L) % 998244353 + 998244353) % 998244353;
        long upperBoundLimit = x * 10L * 1000000L;
        if (x * 1000000 + 999999 <= n_input && upperBoundLimit > n_input) {
            long currentCount = total_nodes;
            int[] sizes = new int[15];
            long[] diffVals = new long[15];

