                int sizeVec = sequences[i].size();
                long diffVal = ((currentCount - x * factor) % 998244353 + 998244353) % 998244353;
                int pos = lowerBound(sequences[i], 1000000000L - diffVal);
                result_value = (int)((result_value + diffVal * sizeVec + prefix_sum[i]) % 1000000007);
                long subtractVal = (998244353L * (sizeVec - pos)) % 1000000007;
                result_value = (int)((result_value - subtractVal + 1000000007) % 1000000007);
                total_nodes += sizeVec;
            }
            return;
        }

        total_nodes++;
        result_value = (int)((result_value + ((total_nodes - x) % 998244353 + 998244353) % 998244353) % 1000000007);
        for (int i = 0; i <= 9; i++) {
            traverse(x * 10 + i);
        }
    }

    static int lowerBound(List<Long> list, long value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
